head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF08056.xml";
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.gubun = "", scwin.select_gubun = "";
scwin.trsIdx; // insert, update 구분

scwin.isFirstLoad = false;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    if (scwin.fr_bz_procs_no != "") {
        var url = "/etn/EtnMktAct.do?method=searchDelist" + "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_MST_INFO + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Mst.DataID = encodeURI(url);
        dts_Mst.reset();
        url = "/etn/EtnMktAct.do?method=searchDelist&DIV_IDX=" + DIV_IDX_ETN_DELLIST_DTL_INFO + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        dts_Isu.DataID = encodeURI(url);
        dts_Isu.reset();
    }
};
scwin.fn_new_onload = function() {
    /* useupdate를 false로 지정함. */
    dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETN_DELLIST_MST_INFO_INOUT";
    dts_Mst.reset();
    if (scwin.select_gubun == "1") {
        //url = "/etn/EtnMktAct.do?method=searchEtnTradingSuspension" + 
        //	   "&DIV_IDX="+DIV_IDX_ETN_ISU_ETN_1 + "&ISU_CD=" + gubun ;
        //dts_Isu.DataID = encodeURI(url);
        dts_Isu.DataID = "/etn/EtnCodeAct.do?method=searchEtnCode&GUBUN=" + scwin.select_gubun + "&ISUR_CD=" + scwin.gubun;
        dts_Isu.reset();
    } else {
        //url = "/Delisting.do?method=searchDelList&DIV_IDX="+DIV_IDX_DELLIST_LIST_ANXTY + "&ISUR_CD=" + Isur_cd ;
        //dts_Isu.DataID = encodeURI(url);
        dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CODE_ETN_OUT";
        dts_Isu.reset();
    }
};
scwin.fn_get_rsn_cd = function() {
    var url = "/listingCommon.do?method=listCode&inputMessageId=LISTING_CODE_IN&outputMessageId=LISTING_CODE_OUT&MKT=" + scwin.Mkt_id + "&RSN=" + "15";
    dts_Rsn.DataID = encodeURI(url);
    dts_Rsn.reset();
};
scwin.fn_GetParIsu = function(arrPar, param_dts) {
    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.select_gubun;
    $c.stf.CopyDataSet(dts_Isu, param_dts);
};
scwin.fn_SetParIsu = function(param_dts) {
    $c.stf.CopyDataSet(param_dts, dts_Isu);
    if (scwin.Isur_cd == "") {
        scwin.Isur_cd = dts_Isu.getCellData(1, "ISUR_CD");
    }
};
scwin.fn_CheckForm = function() {
    if (dts_Isu.getTotalRow() == 0) {
        $c.win.alert("[예고종목]을 선택하세요.");
        img_SetIsuCd.focus();
        return false;
    }
    if (!$c.stf.checkEmptyValue(txb_GrndRegulContn, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_GrndRegulContn, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    return true;
};
scwin.fn_save_trs = function() {
    // 매매거래정지종목은 매번 업무처리 번호를 세팅함
    // 종목별 변경이 있을수 있기 때문
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {
        dts_Isu.setCellData(i, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    }
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", scwin.Isur_cd);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ADVNOTI_RSN_TP_CD", dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "CODE"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "WRT_DD", $c.ut.cGetToday("yyyymmdd"));
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "INFO_CONTN_TP_CD", "9"); // 9 ETN상장폐지예고

    trs.Action = $c.lce.fn_encodeNSession("/etn/EtnMktAct.do?method=saveDelist");
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_Isu)";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=2" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_711 + ",DIV_IDX[0]=" + DIV_IDX_ETN_DELLIST_MST_INFO + ",DIV_IDX[1]=" + DIV_IDX_ETN_DELLIST_DTL_INFO;
    trs.Post();
};
scwin.fn_save = function() {
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            scwin.fn_save_trs();
        }
    }
};
scwin.fn_update = function() {
    if ($c.en.fn_CheckForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lce.fn_isProcess('U')) return;
        scwin.fn_save_trs();
    }
};
scwin.fn_delete = function() {
    if (!$c.lce.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_save_trs();
};
scwin.fn_dscl = async function() {
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        // cmb_Rsn_Cd.BindColVal == "202" 
        if (cmb_Rsn_Cd.BindColVal == "21") {
            arr[0] = "68352A";
        } else if (cmb_Rsn_Cd.BindColVal == "22") {
            arr[0] = "68352B";
        } else if (cmb_Rsn_Cd.BindColVal == "23") {
            arr[0] = "68352C";
        } else if (cmb_Rsn_Cd.BindColVal == "24") {
            arr[0] = "68352D";
        }
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        arr[5] = dts_Isu.getCellData(dts_Isu.getRowPosition(), "ISU_NM");
        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "ADVNOTI_RSN_TP_CD_NM", cmb_Rsn_Cd.getText());
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 15;
    var hgt = 785 + 40;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {

};
scwin.fn_makt = function() {

};
scwin.fn_setRemk = function() {
    if (cmb_Rsn_Cd.BindColVal == "21" || cmb_Rsn_Cd.BindColVal == "22") {
        txa_Remk.Text = "상기 종목은 1개월 이내에 유동성공급 계획의 제출 또는 다른 유동성공급자와 유동성공급 계약을\r\n";
        txa_Remk.Text += "체결하지 않을 경우 상장폐지됨을 알려드립니다.\r\n";
        //txa_Remk.Text = "상기 종목은 유동성공급자를 1개월 이내에 교체하지 않을 경우 상장폐지됨을 알려드립니다.\r\n";

    } else if (cmb_Rsn_Cd.BindColVal == "23") {
        txa_Remk.Text = "상기 종목은 발행회사의 영업용순자본비율 150%가 3개월 지속될 경우 또는\r\n";
        txa_Remk.Text += "해당 기간중에라도 120% 미만이 발생할 경우 즉시 상장폐지됨을 알려드립니다.\r\n";
    } else if (cmb_Rsn_Cd.BindColVal == "10") {
        txa_Remk.Text = "상기 상장지수증권은 만기가 1개월 남았음을 알려드립니다. \r\n";
    } else if (cmb_Rsn_Cd.BindColVal == "24") {
        txa_Remk.Text = "상기 상장지수증권은 발행사의 신청에 따라 0000년 00월 00일 상장폐지 될 예정임을 알려드립니다.\r\n";
        txa_Remk.Text += "(단, 상장폐지 전일 자진 상장폐지 요건(LP 보유비중 95% 이상) 충족 필요)";
    }
};
scwin.fn_SetIsuCdBtnShow = function(initTyp) {
    if (initTyp == "1" || scwin.fr_bz_procs_no != "") {
        img_SetIsuCd.src = "../img/btn_isu_select_d.gif";
        img_SetIsuCd.setDisabled(true);
    } else {
        img_SetIsuCd.src = "../img/btn_isu_select.gif";
        img_SetIsuCd.setDisabled(false);
    }
};
scwin.trs_OnFail = function() {
    $c.lce.fn_alertMsg('F');
};
scwin.trs_OnSuccess = async function() {
    $c.lce.fn_alertMsg('S');
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        buttonSet.setUpdateStatus();
        scwin.fn_search();
    }
};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.fr_bz_procs_no == "") {
        dts_Mst.insertRow();
    }

    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.fr_bz_procs_no == "") {
        buttonSet.setInsertStatus();
    } else {
        buttonSet.setUpdateStatus();
    }
    scwin.isFirstLoad = true;
    if (scwin.fr_bz_procs_no == "") {
        cmb_Rsn_Cd.BindColVal = "21";
        txb_GrndRegulContn.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
        scwin.fn_setRemk();
    } else {
        cmb_Rsn_Cd.BindColVal = dts_Mst.getCellData(dts_Mst.getRowPosition(), "ADVNOTI_RSN_TP_CD");
    }
    scwin.isFirstLoad = false;
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.cmb_Rsn_Cd_OnSelChange2 = function() {
    if (scwin.isFirstLoad) return;
    txb_GrndRegulContn.setValue(dts_Rsn.getCellData(cmb_Rsn_Cd.getSelectedIndex() + 1, "REGL"));
    scwin.fn_setRemk();
};
scwin.cmb_Rsn_Cd_OnSelected = function() {

};
scwin.img_SetIsuCd_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsu;
    scwin.fn_SetPar = fn_SetParIsu;
    $c.lce.fn_PopFindEtnCode();
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
        scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
        scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명(종목명)
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
        scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
        scwin.gubun = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/기초자산 구분값(종목코드값)
        scwin.select_gubun = (arrPar.length >= 7 ? arrPar[6] : ""); //  구분값

    }
    scwin.fn_get_rsn_cd();

    //alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" + 
    //		 "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    if (scwin.fr_bz_procs_no != "") {
        // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
        scwin.fn_search();
    } else {
        scwin.fn_new_onload(); // 신규작성시 호출

    }
    $c.cp.removeRow(dts_Rsn, 1);
    scwin.fn_SetIsuCdBtnShow(scwin.select_gubun);
    $c.libRoundPanel.PanelToGroupBox(panel_3);
};
